def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    from collections import Counter

    counts = Counter(x for row in grid for x in row)
    bg = counts.most_common(1)[0][0]

    # Find the three-cell template. Its middle cell is aligned with each marker.
    template = None
    for r in range(h):
        for c in range(w):
            for dr, dc in ((0, 1), (1, 0)):
                coords = [(r + i * dr, c + i * dc) for i in range(3)]
                if all(0 <= rr < h and 0 <= cc < w for rr, cc in coords):
                    vals = [grid[rr][cc] for rr, cc in coords]
                    if vals[0] != bg and vals[1] != bg and vals[2] != bg and len(set(vals)) >= 2:
                        # Prefer a sequence containing the distinctive color 8 or 5.
                        if 8 in vals or 5 in vals:
                            template = (dr, dc, vals)
                            break
            if template:
                break
        if template:
            break

    if template is None:
        return out

    dr, dc, vals = template
    template_colors = set(vals)
    # Markers are the non-background color outside the template that occurs most.
    candidates = [color for color in counts if color != bg and color not in template_colors]
    if not candidates:
        return out
    marker = max(candidates, key=lambda color: counts[color])

    for r in range(h):
        for c in range(w):
            if grid[r][c] == marker:
                for i, color in enumerate(vals):
                    rr, cc = r + (i - 1) * dr, c + (i - 1) * dc
                    if 0 <= rr < h and 0 <= cc < w:
                        out[rr][cc] = color
    return out
